#include <stdio.h>

int linear(const int values[], int count, int key)
{
    for (int i = 0; i < count; i++) {
        if (values[i] == key) {
            return i;
        }
    }
    return -1;
}

int main(void)
{
    int a[] = {8, 5, 2, 5};
    printf("%d\n", linear(a, 4, 5));
    return 0;
}

#include <stdio.h>

int binary(const int values[], int count, int key)
{
    int low = 0, high = count;
    while (low < high) {
        int middle = low + (high - low) / 2;
        if (values[middle] == key) {
            return middle;
        }
        if (values[middle] < key) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    return -1;
}

int main(void)
{
    int a[1] = {7};
    printf("%d\n", binary(a, 0, 7));
    return 0;
}

#include <stdio.h>

int lower_bound(const int values[], int count, int key)
{
    int low = 0, high = count;
    while (low < high) {
        int middle = low + (high - low) / 2;
        if (values[middle] < key) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    return low;
}

int main(void)
{
    int a[] = {2, 4, 6};
    printf("%d\n", lower_bound(a, 3, 9));
    return 0;
}

